BEGIN;

-- 行をコピーしている間に旧テーブルへ変更が入らないようにする
LOCK TABLE "ProductCategory", "Product", "Customer", "Member", "CustomerAddress",
    "CartItem", "Order", "OrderShippingAddress", "OrderItem" IN ACCESS EXCLUSIVE MODE;

-- ID を先頭にした同名テーブルを作業用スキーマに作る
CREATE SCHEMA thread_id_first;
SET LOCAL search_path TO thread_id_first, public;

CREATE TABLE "Product" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "categoryId" INTEGER NOT NULL,
    "price" INTEGER NOT NULL,
    "stock" INTEGER NOT NULL,
    "isPublished" BOOLEAN NOT NULL DEFAULT true,

    CONSTRAINT "Product_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ProductCategory" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,

    CONSTRAINT "ProductCategory_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Customer" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "email" TEXT NOT NULL,
    "lastName" TEXT NOT NULL,
    "firstName" TEXT,
    "lastNameKana" TEXT,
    "firstNameKana" TEXT,
    "phone" TEXT,
    "passwordHash" TEXT NOT NULL,

    CONSTRAINT "Customer_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "CustomerAddress" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "customerId" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "postalCode" TEXT NOT NULL,
    "prefecture" TEXT NOT NULL,
    "city" TEXT NOT NULL,
    "line1" TEXT NOT NULL,
    "line2" TEXT NOT NULL DEFAULT '',
    "phone" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "CustomerAddress_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Member" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "email" TEXT NOT NULL,
    "lastName" TEXT NOT NULL,
    "firstName" TEXT,
    "passwordHash" TEXT NOT NULL,

    CONSTRAINT "Member_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "CartItem" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "customerId" INTEGER NOT NULL,
    "productId" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,

    CONSTRAINT "CartItem_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Order" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "reference" TEXT NOT NULL,
    "customerId" INTEGER,
    "guestEmail" TEXT,
    "guestAccessHash" TEXT,
    "total" INTEGER NOT NULL,
    "status" "OrderStatus" NOT NULL DEFAULT 'PLACED',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "Order_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "OrderShippingAddress" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "orderId" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "postalCode" TEXT NOT NULL,
    "prefecture" TEXT NOT NULL,
    "city" TEXT NOT NULL,
    "line1" TEXT NOT NULL,
    "line2" TEXT NOT NULL DEFAULT '',
    "phone" TEXT NOT NULL,

    CONSTRAINT "OrderShippingAddress_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "OrderItem" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "orderId" INTEGER NOT NULL,
    "productId" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "unitPrice" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,

    CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Product_code_key" ON "Product"("code");

CREATE INDEX "Product_categoryId_idx" ON "Product"("categoryId");

CREATE UNIQUE INDEX "ProductCategory_code_key" ON "ProductCategory"("code");

CREATE UNIQUE INDEX "Customer_email_key" ON "Customer"("email");

CREATE INDEX "CustomerAddress_customerId_createdAt_idx" ON "CustomerAddress"("customerId", "createdAt");

CREATE UNIQUE INDEX "Member_email_key" ON "Member"("email");

CREATE INDEX "CartItem_productId_idx" ON "CartItem"("productId");

CREATE UNIQUE INDEX "CartItem_customerId_productId_key" ON "CartItem"("customerId", "productId");

CREATE UNIQUE INDEX "Order_reference_key" ON "Order"("reference");

CREATE INDEX "Order_customerId_createdAt_idx" ON "Order"("customerId", "createdAt");

CREATE INDEX "Order_createdAt_idx" ON "Order"("createdAt");

CREATE UNIQUE INDEX "OrderShippingAddress_orderId_key" ON "OrderShippingAddress"("orderId");

CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId");

CREATE INDEX "OrderItem_productId_idx" ON "OrderItem"("productId");

ALTER TABLE "Product" ADD CONSTRAINT "Product_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "ProductCategory"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "CustomerAddress" ADD CONSTRAINT "CustomerAddress_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "CartItem" ADD CONSTRAINT "CartItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Order" ADD CONSTRAINT "Order_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "OrderShippingAddress" ADD CONSTRAINT "OrderShippingAddress_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "Order" ADD CONSTRAINT "Order_buyer_check" CHECK (
    ("customerId" IS NOT NULL AND "guestEmail" IS NULL AND "guestAccessHash" IS NULL)
    OR
    ("customerId" IS NULL AND "guestEmail" IS NOT NULL AND "guestAccessHash" IS NOT NULL)
);

SET LOCAL search_path TO public;

DO $$
DECLARE
    table_name text;
    original regclass;
    replacement regclass;
    columns text;
    previous_sequence regclass;
    next_sequence regclass;
    sequence_value bigint;
    sequence_used boolean;
BEGIN
    FOREACH table_name IN ARRAY ARRAY[
        'ProductCategory', 'Customer', 'Member', 'Product', 'CustomerAddress',
        'CartItem', 'Order', 'OrderShippingAddress', 'OrderItem'
    ] LOOP
        original := format('public.%I', table_name)::regclass;
        replacement := format('thread_id_first.%I', table_name)::regclass;

        -- 演習中に追加した列や制約などをコピー対象から落とさないよう差分を検出する
        IF (
            SELECT array_agg(jsonb_build_array(a.attname, a.atttypid, a.atttypmod, a.attnotnull,
                a.attidentity, a.attgenerated, pg_get_expr(d.adbin, d.adrelid)) ORDER BY a.attname)
            FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
            WHERE a.attrelid = original AND a.attnum > 0 AND NOT a.attisdropped
        ) IS DISTINCT FROM (
            SELECT array_agg(jsonb_build_array(a.attname, a.atttypid, a.atttypmod, a.attnotnull,
                a.attidentity, a.attgenerated, pg_get_expr(d.adbin, d.adrelid)) ORDER BY a.attname)
            FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
            WHERE a.attrelid = replacement AND a.attnum > 0 AND NOT a.attisdropped
        ) OR (
            SELECT array_agg(jsonb_build_array(conname, replace(pg_get_constraintdef(oid), 'REFERENCES public.', 'REFERENCES ')) ORDER BY conname)
            FROM pg_constraint WHERE conrelid = original
        ) IS DISTINCT FROM (
            SELECT array_agg(jsonb_build_array(conname, replace(pg_get_constraintdef(oid), 'REFERENCES thread_id_first.', 'REFERENCES ')) ORDER BY conname)
            FROM pg_constraint WHERE conrelid = replacement
        ) OR (
            SELECT array_agg(replace(pg_get_indexdef(indexrelid), ' ON public.', ' ON ') ORDER BY indexrelid::regclass::text)
            FROM pg_index WHERE indrelid = original
        ) IS DISTINCT FROM (
            SELECT array_agg(replace(pg_get_indexdef(indexrelid), ' ON thread_id_first.', ' ON ') ORDER BY indexrelid::regclass::text)
            FROM pg_index WHERE indrelid = replacement
        ) OR EXISTS (
            SELECT 1 FROM pg_trigger WHERE tgrelid = original AND NOT tgisinternal
        ) OR EXISTS (
            SELECT 1 FROM pg_class WHERE oid = original AND (relacl IS NOT NULL OR relrowsecurity)
        ) THEN
            RAISE EXCEPTION 'カラム順を変更する前に % の独自スキーマ変更を統合してください', table_name;
        END IF;

        SELECT string_agg(quote_ident(attname), ', ' ORDER BY attnum)
        INTO columns
        FROM pg_attribute
        WHERE attrelid = replacement AND attnum > 0 AND NOT attisdropped;
        EXECUTE format('INSERT INTO %s (%s) SELECT %s FROM %s', replacement, columns, columns, original);

        -- MAX(id) ではなく旧シーケンスの状態を移し 削除済みの ID も再利用しない
        previous_sequence := pg_get_serial_sequence(format('public.%I', table_name), 'id')::regclass;
        next_sequence := pg_get_serial_sequence(format('thread_id_first.%I', table_name), 'id')::regclass;
        EXECUTE format('SELECT last_value, is_called FROM %s', previous_sequence)
            INTO sequence_value, sequence_used;
        PERFORM setval(next_sequence, sequence_value, sequence_used);
    END LOOP;
END $$;

-- 他のオブジェクトが旧テーブルを参照している場合はトランザクションごと戻す
DROP TABLE "ProductCategory", "Product", "Customer", "Member", "CustomerAddress",
    "CartItem", "Order", "OrderShippingAddress", "OrderItem";

ALTER TABLE thread_id_first."ProductCategory" SET SCHEMA public;
ALTER TABLE thread_id_first."Product" SET SCHEMA public;
ALTER TABLE thread_id_first."Customer" SET SCHEMA public;
ALTER TABLE thread_id_first."Member" SET SCHEMA public;
ALTER TABLE thread_id_first."CustomerAddress" SET SCHEMA public;
ALTER TABLE thread_id_first."CartItem" SET SCHEMA public;
ALTER TABLE thread_id_first."Order" SET SCHEMA public;
ALTER TABLE thread_id_first."OrderShippingAddress" SET SCHEMA public;
ALTER TABLE thread_id_first."OrderItem" SET SCHEMA public;

DROP SCHEMA thread_id_first;

COMMIT;
